from pathlib import Path
Path('src/main.tsx').write_text('''import './index.css';

import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

import React from 'react';
import ReactDOM from 'react-dom/client';

import { App } from './App';

ReactDOM.createRoot(document.getElementById('root')"'!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);
'"''')

Path('src/App.tsx').write_text('''import { useState } from 'react';
import { Button, Checkbox, Flex, PasswordInput, TextInput } from '@gravity-ui/uikit';

import './App.css';

export function App() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
  };

  return (
    <main className=\"login-page\">
      <form className=\"login-card\" onSubmit={handleSubmit}>
        <Flex direction=\"column\" gap={5}>
          <h1 className=\"login-title\">Вход</h1>
          <TextInput
            type=\"email\"
            name=\"email\"
            label=\"Email\"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            required
          />
          <PasswordInput
            name=\"password\"
            label=\"Пароль\"
            value={password}
            onChange={(event) => setPassword(event.target.value)}
            required
          />
          <Checkbox
            name=\"rememberMe\"
            checked={rememberMe}
            onUpdate={setRememberMe}
          >
            Запомнить меня
          </Checkbox>
          <Button type=\"submit\" view=\"action\" size=\"l\">
            Войти
          </Button>
        </Flex>
      </form>
    </main>
  );
}
''')

Path('src/App.css').write_text('''body {
  margin: 0;
}

.login-page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: var(--g-spacing-4);
  background: var(--g-color-base-background);
}

.login-card {
  width: min(100%, 25rem);
  padding: var(--g-spacing-7);
  border-radius: var(--g-border-radius-l);
  border: 1px solid var(--g-color-base-simple-hover-solid);
  background: var(--g-color-base-float);
  box-shadow: var(--g-color-base-shadow);
}

.login-title {
  margin: 0;
  color: var(--g-color-text-primary);
  font: var(--g-text-header-2-font);
}
''')
PATCH
npm run build"

